import itertools, string
import numpy as np

def name_to_vec(name, k):
    v = 0
    for ch in name:
        v |= (1 << (ord(ch)-97))
    return v

def popcount(x):
    return bin(x).count("1")

def select_generators(k, res, count):
    base_letters = string.ascii_lowercase[:k]
    base_vecs = [1 << i for i in range(k)]
    candidates = [
        "".join(c)
        for r in range(res - 1, k + 1)
        for c in itertools.combinations(base_letters, r)
    ]
    accepted_vecs = list(base_vecs)
    accepted_names = []
    max_subset = res - 2  # existing-subset size to check (plus new candidate = res-1)

    for cand in candidates:
        cvec = name_to_vec(cand, k)
        # check all subsets of accepted_vecs of size 0..max_subset
        safe = True
        pool = accepted_vecs
        for size in range(0, max_subset + 1):
            if not safe:
                break
            for combo in itertools.combinations(pool, size):
                s = cvec
                for c in combo:
                    s ^= c
                if s == 0:
                    safe = False
                    break
        if safe:
            accepted_vecs.append(cvec)
            accepted_names.append(cand)
            if len(accepted_names) == count:
                return accepted_names
    return None

def min_base_factors(n, res):
    import math
    if res == 3:
        return max(2, math.ceil(math.log2(n + 1)))
    k = max(res - 1, math.ceil(math.log2(n + 1)))
    return k

def build(n, res, max_k=20):
    k = min_base_factors(n, res)
    while k <= max_k:
        gens = select_generators(k, res, n - k)
        if gens is not None:
            return k, gens
        k += 1
    return None, None

tests = [
    (4,3),(7,3),(10,3),(16,3),
    (4,4),(8,4),(11,4),
    (5,5),(8,5),(12,5),
    (6,3),(6,5)
]
for n,res in tests:
    k, gens = build(n, res)
    print(n,res,"-> k=",k,"runs=",2**k,"gens=",gens)
